// Author: MiYu. AI build and harvest directives issue paid source commands against actual map entities.
#include "session.h"
#include <algorithm>
#include <bit>
#include <cmath>

namespace war3 {
namespace {float number(jass::Real value){return std::bit_cast<float>(value.bits());}jass::Real real(float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));}float distance(WorldPoint a,WorldPoint b){return std::hypot(number(a.x)-number(b.x),number(a.y)-number(b.y));}}
void ScriptSession::aiTowns(ScriptAI& ai){
    for(auto& [id,u]:units_)if(u->owner==ai.owner && !u->removing && number(u->life)>0 && definitions().unitClasses(u->type).find("townhall")!=std::string::npos && std::find(ai.towns.begin(),ai.towns.end(),id)==ai.towns.end())ai.towns.push_back(id);
    if(ai.homeOverride)return;for(auto id:ai.towns)if(alive(id,NativeKind::Unit) && units_.at(id)->owner==ai.owner && number(units_.at(id)->life)>0){ai.home={units_.at(id)->x,units_.at(id)->y};return;}auto index=config_.players[ai.owner].start;if(index>=0 && config_.starts[index].defined)ai.home={config_.starts[index].position[0],config_.starts[index].position[1]};
}
int ScriptSession::aiTown(ScriptAI& ai,const UnitState& unit){int result=-1;float best=FLT_MAX;for(size_t i=0;i<ai.towns.size();++i)if(alive(ai.towns[i],NativeKind::Unit)){auto hall=units_.at(ai.towns[i]);if(hall->owner!=ai.owner || number(hall->life)<=0)continue;auto d=distance({unit.x,unit.y},{hall->x,hall->y});if(d<best){best=d;result=int(i);}}return result;}
unsigned ScriptSession::aiCount(ScriptAI& ai,std::uint32_t type,bool done,int town){
    unsigned count=0;for(auto& [id,u]:units_)if(u->owner==ai.owner && !u->removing && number(u->life)>0 && (town<0 || aiTown(ai,*u)==town)){if(u->type==type && (!done || !u->construction))++count;if(!done){if(u->buildingUpgrade && u->buildingUpgrade->type==type)++count;if(u->buildOrder && u->buildOrder->type==type)++count;for(auto& job:u->production)if(!job.research && job.type==type)++count;}}return count;
}
std::uint32_t ScriptSession::aiMine(ScriptAI& ai,int town){
    WorldPoint center=ai.home;if(town>=0){if(size_t(town)>=ai.towns.size() || !alive(ai.towns[town],NativeKind::Unit))return 0;auto hall=units_.at(ai.towns[town]);if(hall->owner!=ai.owner || number(hall->life)<=0)return 0;center={hall->x,hall->y};}std::uint32_t result=0;float best=1800;for(auto& [id,u]:units_)if(!u->removing && !u->hidden() && !u->construction && number(u->life)>0 && u->resources>0 && (u->owner>=12 || u->owner==ai.owner) && (sourceAbility(*u,"Agld").first || sourceAbility(*u,"Abgm").first || sourceAbility(*u,"Aegm").first)){auto d=distance(center,{u->x,u->y});if(d<best){result=id;best=d;}}return result;
}
bool ScriptSession::aiProduce(ScriptAI& ai,unsigned quantity,std::uint32_t type,int town){
    if(!quantity || quantity>32 || !definitions().contains(type))return false;std::vector<std::uint32_t> owned;for(auto& [id,u]:units_)if(u->owner==ai.owner && !u->removing && number(u->life)>0 && (town<0 || aiTown(ai,*u)==town))owned.push_back(id);unsigned accepted=0;
    for(unsigned request=0;request<quantity;++request){bool queued=false;for(auto id:owned)if(alive(id,NativeKind::Unit)){auto u=units_.at(id);if(u->buildingUpgrade || u->construction)continue;if(std::find(u->upgradeables.begin(),u->upgradeables.end(),type)!=u->upgradeables.end()){queued=upgradeBuilding(id,type);if(queued)break;}if(std::find(u->trainables.begin(),u->trainables.end(),type)!=u->trainables.end() && u->production.size()<7){queued=train(id,type);if(queued)break;}}
        if(!queued)for(auto id:owned)if(alive(id,NativeKind::Unit)){auto u=units_.at(id);if(u->buildOrder || u->workingOn || u->construction || u->paused || u->hidden() || std::find(u->buildables.begin(),u->buildables.end(),type)==u->buildables.end())continue;WorldPoint center=ai.townSpot.value_or(ai.home);if(town>=0 && size_t(town)<ai.towns.size() && alive(ai.towns[town],NativeKind::Unit)){auto hall=units_.at(ai.towns[town]);center={hall->x,hall->y};}if(definitions().number(type,"UnitData","isBuildOn")!=0){auto mine=aiMine(ai,town);if(mine)queued=build(id,type,{units_.at(mine)->x,units_.at(mine)->y});}else for(unsigned ring=0;ring<10 && !queued;++ring)for(unsigned side=0;side<12 && !queued;++side){float angle=float(side)*6.28318530718f/12;WorldPoint point{real(number(center.x)+std::cos(angle)*(320+ring*128)),real(number(center.y)+std::sin(angle)*(320+ring*128))};bool reserved=false;auto size=buildingSize(type);for(auto other:owned)if(alive(other,NativeKind::Unit)){auto pending=units_.at(other)->buildOrder;if(pending){auto otherSize=buildingSize(pending->type);if(std::abs(number(point.x)-number(pending->point.x))<(size[0]+otherSize[0])/2+64 && std::abs(number(point.y)-number(pending->point.y))<(size[1]+otherSize[1])/2+64){reserved=true;break;}}}if(!reserved)queued=build(id,type,point);}if(queued)break;}if(!queued)break;++accepted;
    }return accepted==quantity;
}
bool ScriptSession::aiUpgrade(ScriptAI& ai,std::uint32_t type){std::vector<std::uint32_t> owned;for(auto& [id,u]:units_)if(u->owner==ai.owner && !u->removing && number(u->life)>0)owned.push_back(id);for(auto id:owned)if(alive(id,NativeKind::Unit)){auto u=units_.at(id);if(std::any_of(u->production.begin(),u->production.end(),[type](auto& job){return job.research && job.type==type;}))return true;}for(auto id:owned)if(alive(id,NativeKind::Unit) && research(id,type))return true;return false;}
void ScriptSession::aiHarvest(ScriptAI& ai){
    if(!ai.gathering)return;for(auto [town,goals]:ai.harvesting){int gold=0,wood=0;std::vector<std::uint32_t> available;for(auto& [id,u]:units_)if(u->owner==ai.owner && !u->removing && !u->building && !u->construction && number(u->life)>0 && (town<0 || aiTown(ai,*u)==town)){if(u->gather.mine)++gold;else if(u->gather.tree)++wood;else if(!u->currentOrder && !u->paused && !u->hidden())available.push_back(id);}auto mine=aiMine(ai,town);for(auto id:available){if(!alive(id,NativeKind::Unit))continue;auto u=units_.at(id);if(gold<goals.first && mine && harvest(id,mine)){++gold;continue;}if(wood<goals.second){auto tree=nearestTree({u->x,u->y},2500);if(tree && harvestTree(id,tree)){++wood;continue;}}}}
}
}
